import{R as e,e as o,f as n,U as i}from"./chunks/framework.ywem4qy5.js";const p=JSON.parse('{"title":"Gorgias","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/help-desk/gorgias.md","filePath":"integrations/help-desk/gorgias.md","lastUpdated":1775908585000}'),r={name:"integrations/help-desk/gorgias.md"};function a(s,t,l,g,h,c){return o(),n("div",null,[...t[0]||(t[0]=[i('<h1 id="gorgias" tabindex="-1">Gorgias <a class="header-anchor" href="#gorgias" aria-label="Permalink to &quot;Gorgias&quot;">​</a></h1><p>Follow the below steps to connect to the Gorgias API.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>Help Desk</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select <strong>Gorgias</strong> as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-gorgias-api" tabindex="-1">Step 2. Connect to the Gorgias API <a class="header-anchor" href="#step-2-connect-to-the-gorgias-api" aria-label="Permalink to &quot;Step 2. Connect to the Gorgias API&quot;">​</a></h3><ol><li>Go to <a href="https://gorgias.com" target="_blank">Gorgias</a> and login to your account.</li><li>Click on your profile dropdown on the top-right of the screen, and select <strong>Settings</strong>.</li><li>In the left-hand sidebar, click the <strong>Settings</strong> icon.</li><li>In the left-hand sidebar, click <strong>REST API</strong>.</li><li>Click the <strong>Create API Key</strong> button.</li><li>Copy the <strong>Base API URL</strong> from Gorgias and paste in the <strong>API URL</strong> field in Formie.</li><li>Copy the <strong>Username</strong> from Gorgias and paste in the <strong>Username</strong> field in Formie.</li><li>Copy the <strong>Password</strong> from Gorgias and paste in the <strong>API Key</strong> field in Formie.</li></ol><h3 id="step-3-test-connection" tabindex="-1">Step 3. Test Connection <a class="header-anchor" href="#step-3-test-connection" aria-label="Permalink to &quot;Step 3. Test Connection&quot;">​</a></h3><ol><li>Save this integration.</li><li>Click on the <strong>Refresh</strong> button in the right-hand sidebar.</li></ol><h3 id="step-4-form-setting" tabindex="-1">Step 4. Form Setting <a class="header-anchor" href="#step-4-form-setting" aria-label="Permalink to &quot;Step 4. Form Setting&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Click the <strong>Integrations</strong> tab.</li><li>In the left-hand sidebar, select the name you gave the integration.</li><li>Enable the integration and fill out all required fields.</li><li>Click <strong>Save</strong> to save the form.</li></ol>',10)])])}const f=e(r,[["render",a]]);export{p as __pageData,f as default};
